def clipm(m,lo,hi):
    for ax in range(3):
        n=[0,0,0]; n[ax]=1; m=m.slice_plane([lo[0],lo[1],lo[2]],n,cap=True)
        n=[0,0,0]; n[ax]=-1; m=m.slice_plane([hi[0],hi[1],hi[2]],n,cap=True)
    return m
